compile.workshop:
variables {
    global:
        0: g
}

rule ("defaults") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Kill(Event Player, Null);
        Damage(Event Player, Null, 10);
        Heal(Event Player, Null, 5);
        Create Effect(All Players(All Teams), Good Aura, Color(Yellow), Event Player, 3, Visible To Position Radius and Color);
        Start Healing Modification(All Players(All Teams), All Players(All Teams), 50, Receivers Healers and Healing Percent);
        Set Objective Description(All Players(All Teams), Custom String("obj"), Visible To Sort Order String and Color);
        Create In-World Text(All Players(All Teams), Custom String("hi"), Vector(0, 0, 0), 2, Do Not Clip, Visible To Position String and Color, Color(White), Default Visibility);
        Create Progress Bar HUD Text(Event Player, 5, Null, Left, 0, Color(White), Color(White), Visible To Values and Color, Default Visibility);
        Create Progress Bar In-World Text(All Players(All Teams), 0, Null, Vector(0, 0, 0), 1, Do Not Clip, Color(White), Color(White), Visible To Position Values and Color, Default Visibility);
        Create HUD Text(All Players(All Teams), Null, Custom String("hi"), Null, Left, 0, Null, Color(White), Null, Visible To Sort Order String and Color, Default Visibility);
        Create HUD Text(All Players(All Teams), Null, Custom String("hi"), Null, Left, 0, Null, Color(White), Null, Visible To Sort Order String and Color, Default Visibility);
        Create Dummy Bot(Hero(Ana), All Teams, 0, Vector(0, 0, 0), Vector(0, 0, 0));
        Create Beam Effect(Event Player, Good Beam, Vector(0, 0, 0), Vector(0, 0, 0), Null, Visible To Position Radius and Color);
        Set Global Variable(g, Players In Slot(1, All Teams));
        Set Global Variable(g, All Players On Objective(All Teams));
        Set Global Variable(g, Number Of Slots(All Teams));
        Set Global Variable(g, Players On Hero(Hero(Ana), All Teams));
        Set Global Variable(g, Filtered Array(Players Within Radius(Vector(0, 0, 0), 3, All Teams, Off), And(Is Alive(Current Array Element), Has Spawned(Current Array Element))));
    }
}

